function lineGroup(items,color,opacity,dashed=false){const group=new THREE.Group();for(const item of items){if(item.enabled===false||item.points.length<2)continue;const pts=[];for(let i=1;i<item.points.length;i++){const a=item.points[i-1],b=item.points[i],steps=Math.max(1,Math.ceil(Math.hypot(b[0]-a[0],b[1]-a[1])/2));for(let j=0;j<steps;j++){const t=j/steps;pts.push(point(a[0]+(b[0]-a[0])*t,a[1]+(b[1]-a[1])*t,.5));}}pts.push(point(...item.points.at(-1).slice(0,2),.5));const mat=dashed?new THREE.LineDashedMaterial({color,transparent:true,opacity,dashSize:3,gapSize:2}):new THREE.LineBasicMaterial({color:item.majorRoute===false?'#b2b797':color,transparent:true,opacity:item.majorRoute===false?.55:opacity});const line=new THREE.Line(new THREE.BufferGeometry().setFromPoints(pts),mat);if(dashed)line.computeLineDistances();line.userData.routeId=item.id;group.add(line);}world.add(group);return group;}
