function refreshNetwork(){economy?.invalidate();if(layers.roads){const visible=layers.roads.visible;disposeLayer(layers.roads);layers.roads=lineGroup(routesOfKind('road'),'#d2be91',.9);layers.roads.visible=visible;}if(layers.seaways){const visible=layers.seaways.visible;disposeLayer(layers.seaways);layers.seaways=lineGroup(routesOfKind('sea'),'#8acbd3',.9,true);layers.seaways.visible=visible;}for(const l of labelNodes.filter(l=>l.route))l.node.remove();labelNodes=labelNodes.filter(l=>!l.route);for(const r of D.routes.filter(r=>r.enabled!==false&&r.majorRoute!==false)){const node=document.createElement('span');node.className='mapLabel feature '+(r.kind==='sea'?'waterLabel':'');node.textContent=r.name;node.classList.add('routeLabel');node.setAttribute('role','button');node.tabIndex=0;node.onclick=e=>{e.stopPropagation();networkEditor.open({id:r.id});};node.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();networkEditor.open({id:r.id});}};$('#labels').append(node);labelNodes.push({node,route:r});}dirty=true;}

