function vegetation(){const instances=[];for(const c of D.cells){if(!land(c)||![5,6,7,8,9,12].includes(c.biome)||c.h>82)continue;const n=c.biome===12?2:5+Math.floor(rand()*5);for(let k=0;k<n;k++){const a=D.vertices[c.v[Math.floor(rand()*c.v.length)]].p,t=rand()*.85,x=c.p[0]+(a[0]-c.p[0])*t,y=c.p[1]+(a[1]-c.p[1])*t;instances.push([x,y,1.7+rand()*3,c.biome])}}
 const geom=new THREE.ConeGeometry(1,3.6,5);geom.translate(0,1.8,0);const mesh=new THREE.InstancedMesh(geom,new THREE.MeshStandardMaterial({roughness:1}),instances.length),trunkGeo=new THREE.CylinderGeometry(.17,.24,1.2,4);trunkGeo.translate(0,.5,0);const trunk=new THREE.InstancedMesh(trunkGeo,new THREE.MeshStandardMaterial({color:'#766343'}),instances.length);const obj=new THREE.Object3D();instances.forEach(([x,y,s,b],i)=>{obj.position.copy(point(x,y,.15));obj.scale.set(s*.55,s*.65,s*.55);obj.rotation.y=rand()*Math.PI;obj.updateMatrix();mesh.setMatrixAt(i,obj.matrix);mesh.setColorAt(i,new THREE.Color(b===9?'#355b50':b===12?'#54725b':'#315e46').multiplyScalar(.8+rand()*.4));trunk.setMatrixAt(i,obj.matrix)});layers.trees=new THREE.Group();layers.trees.add(trunk,mesh);world.add(layers.trees)}
const stone=new THREE.MeshStandardMaterial({color:'#dfcba2',roughness:.95}),roof=new THREE.MeshStandardMaterial({color:'#76584b',roughness:.9}),goldMat=new THREE.MeshStandardMaterial({color:'#d8b977',roughness:.4});
const cityMark=b=>(b.capital?'♛ ':'')+(b.magicSchool?'♜ ':b.dwarven?'⛏ ':b.majorPort?(b.settlementClass?.startsWith('Forte')||b.citadel?'⚓⚑ ':'⚓ '):b.settlementClass?.startsWith('Forte')?'⚑ ':'');
function cities(){layers.cities=new THREE.Group();world.add(layers.cities);for(const b of D.cities){const group=new THREE.Group();group.position.copy(point(b.x,b.y,.4));const capital=!!b.capital;const village=b.settlementClass==='Vila';if(village)group.scale.setScalar(.65);if(b.majorPort&&b.harbor){const dock=portModel({fortified:!!b.citadel||b.settlementClass?.startsWith('Forte'),flag:state(b.state)?.color||'#c0392b'});dock.position.copy(point(...b.harbor.waterPoint,.6));layers.cities.add(dock);}const fort=b.settlementClass?.startsWith('Forte')||(edits.cities[b.i]?.features?!!b.citadel:['Winterhelm','Asgorath','Dagorah','Torre Solitária'].includes(b.name));if(b.magicSchool){const mt=mageTowerModel();retexture(mt);group.add(mt)}else if(b.dwarvenFortress){const dm=dwarvenModel();retexture(dm);group.add(dm)}else group.add(settlementModel({b,capital,village,fort,color:state(b.state)?.color||'#c0392b'}));const ring=new THREE.Mesh(new THREE.RingGeometry(capital?6:3.2,capital?6.5:3.5,32),new THREE.MeshBasicMaterial({color:capital?'#f9d68b':'#b6c6ac',side:THREE.DoubleSide,transparent:true,opacity:.75}));ring.rotation.x=-Math.PI/2;ring.position.y=.1;group.add(ring);group.userData.city=b;cityModels.push(group);layers.cities.add(group);const node=document.createElement('span');node.className='mapLabel'+(capital?' capital':'')+(b.dwarven?' dwarven':'')+(b.majorPort?' majorPort':'')+(b.magicSchool?' magicSchool':'');node.textContent=cityMark(b)+title(b);$('#labels').append(node);labelNodes.push({node,b})}
 for(const s of D.states.filter(s=>s.i&&s.pole)){const node=document.createElement('span');node.className='mapLabel state';node.textContent=stateTitle(s);$('#labels').append(node);labelNodes.push({node,s})}refreshVisibility()}
