function refreshVisibility(){for(const g of cityModels)g.visible=visible(g.userData.city);$('#selectionCount').textContent=`${D.cities.filter(visible).length} localidades nesta edição`;$('#counts').textContent=`19 ESTADOS  /  ${D.cities.filter(visible).length} LOCALIDADES`;dirty=true;renderList()}
function renderList(){const q=$('#search').value.normalize('NFD').replace(/\p{Diacritic}/gu,'').toLowerCase();const match=s=>s.normalize('NFD').replace(/\p{Diacritic}/gu,'').toLowerCase().includes(q);let html='';$('#exploreOrder').value=tab==='places'?'name':getListOrder();$('#exploreOrder').disabled=tab==='places';$('#poiActions').hidden=tab!=='places';$('#sidebar .cityActions').hidden=tab==='places';if(tab==='states'){for(const s of D.states.filter(s=>s.i&&match(stateTitle(s))).sort((a,b)=>(getListOrder()==='population'?D.cities.filter(c=>c.state===b.i).reduce((n,c)=>n+inhabitants(D,c),0)-D.cities.filter(c=>c.state===a.i).reduce((n,c)=>n+inhabitants(D,c),0):0)||stateTitle(a).localeCompare(stateTitle(b),'pt-BR'))){const count=D.cities.filter(b=>b.state===s.i&&visible(b)).length;html+=`<button class="result" data-state="${s.i}"><i class="swatch" style="background:${esc(s.color)}"></i><span><strong>${esc(stateTitle(s))}</strong><small>${count} localidades · ${esc(s.formName||'Território')}</small></span><span class="arrow">↗</span></button>`}}else if(tab==='places'){for(const l of orderItems(D.landmarks||[],'name')){const index=D.landmarks.indexOf(l);if(!match(l.name))continue;html+=`<button class="result" data-place="${index}"><i class="swatch" style="background:#9ac2be"></i><span><strong>${esc(l.name)}</strong><small>${esc(l.kind)}</small></span><span class="arrow">↗</span></button>`}}else{for(const b of D.cities.filter(b=>!b.excluded&&(visible(b)||q)&&(match(title(b))||(b.aliases||[]).some(match))).sort((a,b)=>(getListOrder()==='population'?inhabitants(D,b)-inhabitants(D,a):0)||title(a).localeCompare(title(b),'pt-BR'))){html+=`<button class="result" data-city="${b.i}"><i class="swatch" style="background:${esc(state(b.state)?.color||'#aaa')}"></i><span><strong>${b.capital?'♛ ':''}${esc(title(b))}</strong><small>${esc(state(b.state)?.name?.trim()||'Terras livres')} · ${pop(b)} hab.${!visible(b)?' · fora da seleção':''}</small></span><span class="arrow">↗</span></button>`}}$('#results').innerHTML=html||'<p class="empty">Nenhum lugar encontrado.<br>Tente outro nome.</p>';$$('#results [data-state]').forEach(el=>el.onclick=()=>selectState(+el.dataset.state,true));$$('#results [data-city]').forEach(el=>el.onclick=()=>selectCity(+el.dataset.city,true));$$('#results [data-place]').forEach(el=>el.onclick=()=>selectPlace(+el.dataset.place,true))}
function focus(x,y,distance=280){const p=point(x,y);p.y*=relief;const dir=camera.position.clone().sub(controls.target).normalize();if(dir.y<.35)dir.y=.65;dir.normalize();flight={t:0,from:camera.position.clone(),targetFrom:controls.target.clone(),to:p.clone().addScaledVector(dir,distance),target:p};dirty=true}
function showDetail(html){$('#detail').hidden=false;$('#detail').innerHTML='<button class="closeDetail" title="Fechar">✕</button>'+html;$('#detail .closeDetail').onclick=()=>{$('#detail').hidden=true;selected=null;highlight(null)};}
function highlight(sid){const colors=terrain.geometry.attributes.color;const base=mode.startsWith('economic')?(economicColors||naturalColors):['culture','religion'].includes(mode)?(societyColors[mode]||naturalColors):mode==='provinces'?(provinceColors||naturalColors):mode==='population'?(populationColors||naturalColors):mode==='political'?politicalColors:naturalColors;colors.array.set(base);if(sid!=null&&!['population','provinces','culture','religion'].includes(mode)&&!mode.startsWith('economic')){for(let i=0;i<faceCells.length;i++){if(cell(faceCells[i]).state!==sid)continue;for(let j=i*9;j<i*9+9;j+=3){colors.array[j]=Math.min(1,colors.array[j]*1.14+.06);colors.array[j+1]=Math.min(1,colors.array[j+1]*1.12+.035)}}}colors.needsUpdate=true;dirty=true}

function emblem(entity,region=null){const own=entity.emblem,asset=own||region?.emblem;const name=own?entity.name:region?.name;
 if(asset)return `<figure class="crestCard"><img src="${esc(asset)}" alt="Brasão de ${esc(name?.trim())}"></figure>`;
 const initials=(entity.name||'?').trim().split(/\s+/).slice(0,2).map(x=>x[0]).join('');return `<figure class="crestCard fallback"><span>${esc(initials)}</span></figure>`;
}
function selectionState(){if(!selected)return null;if(selected.kind==='state')return selected.id;if(selected.kind==='province')return selected.state;if(selected.kind==='city')return city(selected.id)?.state;const l=D.landmarks[selected.id];return l?nearest(...l.point).state:null}
