function refreshSociety(){if(!society)return;society.refresh();societyColors={};if(['culture','religion'].includes(mode)){ensureSocietyColors(mode);highlight(selectionState());}miniBase=null;dirty=true;}
function ensureSocietyColors(kind){if(societyColors[kind]||!society)return;const data=new Float32Array(naturalColors.length);for(const c of D.cells){if(!land(c))continue;const color=society.color(kind,c.i);let offset=cellFaceStart[c.i];for(const tri of triangles(c))for(const v of tri){data.set([color.r,color.g,color.b],offset);offset+=3;}}societyColors[kind]=data;}
