function keyboardMove(now){const dt=Math.min(.05,(now-(keyboardTime||now))/1000);keyboardTime=now;if(networkEditor?.dragging||painting?.drawing||!keys.size||document.querySelector('dialog[open]')||['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName))return;const forward=controls.target.clone().sub(camera.position);forward.y=0;forward.normalize();const right=new THREE.Vector3().crossVectors(forward,new THREE.Vector3(0,1,0));const delta=new THREE.Vector3();if(keys.has('KeyW')||keys.has('ArrowUp'))delta.add(forward);if(keys.has('KeyS')||keys.has('ArrowDown'))delta.sub(forward);if(keys.has('KeyD')||keys.has('ArrowRight'))delta.add(right);if(keys.has('KeyA')||keys.has('ArrowLeft'))delta.sub(right);if(delta.lengthSq()){flight=null;delta.normalize().multiplyScalar(camera.position.distanceTo(controls.target)*.7*dt*(keys.has('ShiftLeft')||keys.has('ShiftRight')?2.5:1));camera.position.add(delta);controls.target.add(delta);dirty=true}else{const closer=keys.has('ShiftLeft')||keys.has('ShiftRight'),farther=keys.has('ControlLeft')||keys.has('ControlRight');if(closer!==farther){flight=null;zoom(Math.exp((closer?-1:1)*dt*1.1))}}}

