 if(m.startsWith('economic'))refreshEconomicColors(m,economicGood);else economicOverlay?.refresh(m,null);if(economyTraffic)economyTraffic.setEnabled(m.startsWith('economic'));if($('#economicLegend'))$('#economicLegend').hidden=!m.startsWith('economic');
