function economicCellStyle(c){const map=economy.maps();return mode==='economicGoods'?goodColor(map.goodsField[c.i]):map.marketInfo.get(map.marketField[c.i])?.color||'#535c66';}
function zoom(k){camera.position.sub(controls.target).multiplyScalar(k).add(controls.target);controls.update();dirty=true}
