function hitForEditor(e){const ray=new THREE.Raycaster();ray.setFromCamera(new THREE.Vector2(e.clientX/innerWidth*2-1,-e.clientY/innerHeight*2+1),camera);const hit=ray.intersectObject(terrain)[0],p=hit?.point||ray.ray.intersectPlane(new THREE.Plane(new THREE.Vector3(0,1,0),-SEA_LEVEL*relief),new THREE.Vector3());if(!p)return null;const xy=[p.x+W/2,p.z+H/2];return xy[0]>=0&&xy[0]<=W&&xy[1]>=0&&xy[1]<=H?xy:null;}
function exportEdition(){return {format:'silvengard-atlas-v1',exportedAt:new Date().toISOString(),edits,journeys:journeys.exportData(),mapEdits:painting.exportData(),networkEdits:networkEditor.exportData(),provinceEdits:provincePreview?.exportData(),landmarkEdits:placeManager.exportData(),economyEdits:economy?.exportData(),economyState:economy?.exportState()};}
async function defineDefaults(){
 if(networkEditor.hasUnsaved)return toast('Salve ou descarte a edição da rota antes de definir o padrão.');
 try{
  if(selected?.kind==='city'&&$('#cityPopulation'))cityManager.storeForm(selected.id);
  else if(selected?.kind==='state'&&$('#saveDetail'))$('#saveDetail').click();
  const button=$('#defineDefaults');button.disabled=true;button.textContent='Salvando padrão…';
  const response=await fetch('/api/defaults',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({baseId:D.savedDefaults?.id||'base-v23',edition:exportEdition()})});
  let result;try{result=await response.json();}catch{throw Error('Reabra o Atlas pelo Silvengard-Atlas.exe para ativar o salvamento local.');}
  if(!response.ok)throw Error(result.error||'Não foi possível salvar.');
  toast('Padrão salvo nos arquivos do Atlas. Recarregando…');location.reload();
 }catch(e){toast(e.message);$('#defineDefaults').disabled=false;$('#defineDefaults').textContent='Definir como padrão';}
}
