 $('#routesBtn').onclick=()=>{characters?.close();board?.close();provincePreview?.close();cityManager.cancel();networkEditor.open()};$('#editorBtn').onclick=()=>{characters?.close();board?.close();cityManager.cancel();networkEditor.close();painting.open();};$('#charactersBtn').onclick=()=>{board?.close();street?.exit();provincePreview?.close();cityManager.cancel();painting.close();networkEditor.close();journeys.cancel();$('#journeys').hidden=true;$('#detail').hidden=true;characters?.open();};$('#boardBtn').onclick=()=>{characters?.close();street?.exit();provincePreview?.close();cityManager.cancel();painting.close();networkEditor.close();journeys.cancel();$('#journeys').hidden=true;$('#detail').hidden=true;board?.open();};$('#journeysBtn').onclick=()=>{characters?.close();board?.close();provincePreview?.close();cityManager.cancel();painting.close();networkEditor.close();journeys.open();};$('#search').oninput=renderList;for(const t of ['states','cities','places'])$('#'+t+'Tab').onclick=()=>{tab=t;for(const k of ['states','cities','places'])$('#'+k+'Tab').classList.toggle('active',k===t);renderList()};$('#createCity').onclick=()=>cityManager.create();$('#restoreCities').onclick=()=>cityManager.showDeleted();$('#population').onclick=()=>changeMode('population');$('#provinces').onclick=()=>provincePreview?.openMenu();$('#populationBars').onchange=e=>{populationBars=e.target.checked;populationLayer.visible=populationBars;$('#populationLegend').hidden=mode!=='population'&&!populationBars;dirty=true;};$('#natural').onclick=()=>changeMode('natural');$('#political').onclick=()=>changeMode('political');$('#home').onclick=home;$('.brand').onclick=e=>{e.preventDefault();home()};$('#plus').onclick=()=>zoom(.78);$('#minus').onclick=()=>zoom(1.28);$('#topView').onclick=()=>{const dist=camera.position.distanceTo(controls.target);flight={t:0,from:camera.position.clone(),targetFrom:controls.target.clone(),to:controls.target.clone().add(new THREE.Vector3(0,dist,.1)),target:controls.target.clone()}};$('#layersBtn').onclick=()=>{$('#layerOptions').hidden=!$('#layerOptions').hidden;$('#layerOptions').style.display=$('#layerOptions').hidden?'none':'grid'};$$('[data-layer]').forEach(el=>el.onchange=()=>{layers[el.dataset.layer].visible=el.checked;dirty=true});$('#borderSize').value=borderSize;renderer.domElement.dataset.borderSize=borderSize;$('#borderSize').onchange=e=>{borderSize=e.target.value;renderer.domElement.dataset.borderSize=borderSize;layers.borders.userData.fine.visible=borderSize!=='large';layers.borders.userData.large.visible=borderSize==='large';try{localStorage.setItem('silvengard-border-size',borderSize)}catch{}dirty=true};$('#labelsToggle').onchange=e=>{labelsEnabled=e.target.checked;dirty=true};$('#shadowToggle').onchange=e=>{shadowsOn=e.target.checked;renderer.shadowMap.enabled=shadowsOn;scene.traverse(o=>{if(o.material)o.material.needsUpdate=true});dirty=true};$('#waterToggle').onchange=e=>{waterAnim=e.target.checked;dirty=true};$('#relief').oninput=e=>{relief=+e.target.value;world.scale.y=relief;dirty=true};$('#fullBtn').onclick=()=>{if(document.fullscreenElement)document.exitFullscreen();else document.documentElement.requestFullscreen().catch(()=>toast('Use F11 para entrar em tela cheia.'))};$('#referenceBtn').onclick=()=>references();$('#closeModal').onclick=()=>$('#modal').close();$('#modal').onclick=e=>{if(e.target===$('#modal'))$('#modal').close()};$('#helpBtn').onclick=()=>{$('#modalBody').innerHTML='<div class="eyebrow">GUIA DO EXPLORADOR</div><h2>O mundo em suas mãos.</h2><p><kbd>W A S D</kbd> ou <kbd>↑ ← ↓ →</kbd> movem a câmera pelo terreno. <kbd>Shift</kbd> com WASD acelera; <kbd>Shift</kbd> sozinho aproxima e <kbd>Ctrl</kbd> afasta. As teclas não movem o mapa durante a edição de textos.</p><p><kbd>Arrastar</kbd> gira o mapa. <kbd>Roda</kbd> aproxima e afasta. <kbd>Botão direito + arrastar</kbd> move a câmera. No celular, um dedo gira e dois dedos movem ou ajustam o zoom.</p><p>Clique no terreno para ver o estado e o bioma. Clique em uma cidade ou busque pelo nome para abrir sua ficha. As árvores e construções aparecem em volume; o controle de relevo ajusta a altura visual.</p><p>Edite nomes, anotações e a seleção de cidades nas fichas. As alterações ficam neste navegador. Abra <b>Jornadas</b> para criar grupos, traçar percursos terrestres, simular ritmo e terreno e registrar o histórico. A posição atual aparece com um marcador dourado; caminhos percorridos ficam verdes. Use <b>Exportar edição</b> para guardar uma cópia e <b>Importar</b> para restaurá-la em outro navegador.</p><p>O mapa combina células e rotas do .map com rios, cadeias de montanhas e biomas adaptados às referências. Valar recupera seu terreno original e permite ativar névoa nas camadas. Há floresta morta entre os rios de Adhuc Vivere e em Dungabás. As fronteiras podem ser ocultadas ou exibidas como pontilhado fino ou grande nas camadas. Fortes têm muralhas e torres; os fortes élficos marcam a costa leste de Vitravion. O relevo tem exagero visual; as árvores e edifícios são representações ilustrativas. As estradas de Dragonfall, Elucitor e Vitravion foram reconectadas às cidades selecionadas, contornando água e relevos. As demais regiões preservam a rede original.</p><p>Nas referências, alguns nomes são difíceis de ler. Localidades acrescentadas têm posição aproximada, identificada na ficha. Os arquivos de origem permanecem intactos.</p>';$('#modal').showModal()};
 $('#export').onclick=()=>{const content=exportEdition();const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(content,null,2)],{type:'application/json'}));a.download='silvengard-edicao.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),2000);toast('Edição exportada')};$('#import').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>20000000)throw Error('Arquivo muito grande');const d=JSON.parse(await f.text());if(d.format!=='silvengard-atlas-v1'||!d.edits?.cities||!d.edits?.states)throw Error('Formato inválido');const clean={cities:{},states:{}};for(const kind of ['cities','states'])for(const [id,v]of Object.entries(d.edits[kind])){if(!/^\d+$/.test(id)||!v||typeof v!=='object')continue;const z={};if(kind==='cities')Object.assign(z,cityManager.validate(v));if(typeof v.name==='string')z.name=v.name.slice(0,100);if(typeof v.notes==='string')z.notes=v.notes.slice(0,20000);for(const field of ['language','ruler','dynasty','history'])if(typeof v[field]==='string')z[field]=v[field].slice(0,field==='history'?20000:150);if(kind==='cities'&&typeof v.visible==='boolean')z.visible=v.visible;clean[kind][id]=z}if(d.economyState)economy.validateState(d.economyState);if(d.economyEdits)economy.validate(d.economyEdits);if(d.landmarkEdits)placeManager.validate(d.landmarkEdits);if(d.provinceEdits)provincePreview.validate(d.provinceEdits,d.mapEdits);if(d.mapEdits)validateMapEdits(d.mapEdits,D);if(d.networkEdits)cleanNetwork(d.networkEdits,{...D,cities:[...D.cities,...Object.keys(clean.cities).filter(id=>clean.cities[id].created&&!clean.cities[id].deleted).map(id=>({i:+id}))]});if(d.journeys)journeys.importData(d.journeys);if(d.mapEdits)painting.importData(d.mapEdits);if(d.provinceEdits)provincePreview.importData(d.provinceEdits);edits=clean;cityManager.applyStored(true);if(d.networkEdits)networkEditor.importData(d.networkEdits);if(d.landmarkEdits)placeManager.importData(d.landmarkEdits);if(d.economyEdits)economy.importData(d.economyEdits);if(d.economyState)economy.importState(d.economyState);cityManager.reconcileRoutes();refreshCityViews();save();for(const l of labelNodes){if(l.b)l.node.textContent=cityMark(l.b)+title(l.b);else if(l.s)l.node.textContent=stateTitle(l.s)}refreshVisibility();$('#detail').hidden=true;toast('Edição importada')}catch(e){toast('Não foi possível importar: '+e.message)}finally{e.target.value=''}};
 $('#mini').onclick=e=>{const r=e.target.getBoundingClientRect();focus((e.clientX-r.left)/r.width*W,(e.clientY-r.top)/r.height*H,400)};
